#include "wled.h"
#include "serial_json_frame.h"

// forward declarations
static void sendBytes();

/*
 * Adalight and TPM2 handler
 */

enum class AdaState {
  Header_A,
  Header_d,
  Header_a,
  Header_CountHi,
  Header_CountLo,
  Header_CountCheck,
  Data_Red,
  Data_Green,
  Data_Blue,
  TPM2_Header_Type,
  TPM2_Header_CountHi,
  TPM2_Header_CountLo,
};

static uint16_t currentBaud = 1152; //default baudrate 115200 (divided by 100)
static bool continuousSendLED = false;
static uint32_t lastUpdate = 0;

// AI: below section was generated by an AI
static SerialJsonFrame<JSON_BUFFER_SIZE> serialJson;
static uint32_t jsonReceived = 0, jsonErrors = 0, jsonTimeouts = 0;
static uint32_t colorRequests = 0;
static int lastJsonError = 0;
static volatile uint32_t uartOverflows = 0, uartFrameErrors = 0;

void initSerialDiagnostics() {
  #if defined(ARDUINO_ARCH_ESP32) && !ARDUINO_USB_CDC_ON_BOOT
  // Service RX before the 128-byte hardware FIFO is nearly full. The default
  // high threshold leaves very little interrupt-latency headroom at high baud.
  Serial.setRxFIFOFull(32);
  Serial.onReceiveError([](hardwareSerial_error_t error) {
    if (error == UART_FIFO_OVF_ERROR || error == UART_BUFFER_FULL_ERROR) ++uartOverflows;
    else if (error != UART_NO_ERROR) ++uartFrameErrors;
  });
  #endif
}

void serializeSerialDiagnostics(JsonObject root) {
  JsonObject info = root.createNestedObject("RGBBridgeSerial");
  info["jsonReceived"] = jsonReceived;
  info["jsonErrors"] = jsonErrors;
  info["jsonTimeouts"] = jsonTimeouts;
  info["lastJsonError"] = lastJsonError;
  info["uartOverflows"] = uartOverflows;
  info["uartFrameErrors"] = uartFrameErrors;
  info["colorRequests"] = colorRequests;
  info["bufferedBytes"] = serialJson.length;
  info["baud"] = uint32_t(currentBaud) * 100;
}

// Only parse complete, buffered objects. Partial serial delivery must not hold
// the render loop or the shared JSON lock while waiting for the sender.
static void processSerialJson() {
  if (!serialJson.ready) return;
  if (serialJson.overflow) { serialJson.reset(); return; }
  if (!requestJSONBufferLock(JSON_LOCK_SERIAL)) return;
  DeserializationError error = deserializeJson(*pDoc, serialJson.data, serialJson.length);
  ++jsonReceived;
  if (error) { ++jsonErrors; lastJsonError = int(error.code()); }
  if (!error) {
    const bool verboseResponse = deserializeState(pDoc->as<JsonObject>());
    if (verboseResponse && serialCanTX) {
      pDoc->clear();
      JsonObject stateDoc = pDoc->createNestedObject("state");
      serializeState(stateDoc);
      JsonObject info = pDoc->createNestedObject("info");
      serializeInfo(info);
      serializeJson(*pDoc, Serial);
      Serial.println();
    }
  }
  releaseJSONBufferLock();
  serialJson.reset();
}
// AI: end

void updateBaudRate(uint32_t rate){
  unsigned rate100 = rate/100;
  if (rate100 == currentBaud || rate100 < 96) return;
  currentBaud = rate100;

  if (serialCanTX){
    Serial.print(F("Baud is now ")); Serial.println(rate);
  }

  Serial.flush();
  Serial.begin(rate);
  #if defined(ARDUINO_ARCH_ESP32) && !ARDUINO_USB_CDC_ON_BOOT
  Serial.setRxFIFOFull(32);
  #endif
}

// RGB LED data return as JSON array. Slow, but easy to use on the other end.
static inline void sendJSON(){
  if (serialCanTX) {
    unsigned used = strip.getLengthTotal();
    Serial.write('[');
    for (unsigned i=0; i<used; i++) {
      Serial.print(strip.getPixelColor(i));
      if (i != used-1) Serial.write(',');
    }
    Serial.println("]");
  }
}

// RGB LED data returned as bytes in TPM2 format. Faster, and slightly less easy to use on the other end.
static void sendBytes(){
  if (serialCanTX) {
    Serial.write(0xC9); Serial.write(0xDA);
    unsigned used = strip.getLengthTotal();
    unsigned len = used*3;
    Serial.write(highByte(len));
    Serial.write(lowByte(len));
    for (unsigned i=0; i < used; i++) {
      uint32_t c = strip.getPixelColor(i);
      Serial.write(qadd8(W(c), R(c))); //R, add white channel to RGB channels as a simple RGBW -> RGB map
      Serial.write(qadd8(W(c), G(c))); //G
      Serial.write(qadd8(W(c), B(c))); //B
    }
    Serial.write(0x36); Serial.write('\n');
  }
}

void handleSerial()
{
  if (!(serialCanRX && Serial)) return; // arduino docs: `if (Serial)` indicates whether or not the USB CDC serial connection is open. For all non-USB CDC ports, this will always return true

  static auto state = AdaState::Header_A;
  static uint16_t count = 0;
  static uint16_t pixel = 0;
  static byte check = 0x00;
  static byte red   = 0x00;
  static byte green = 0x00;

  // AI: below section was generated by an AI
  if (serialJson.ready) { processSerialJson(); return; }
  if (serialJson.active && uint32_t(millis() - serialJson.lastByteMs) >= 1000) {
    ++jsonTimeouts;
    serialJson.reset();
  }
  const uint32_t receiveStartUs = micros();
  unsigned received = 0;
  // AI: end

  while (Serial.available() > 0)
  {
    // AI: below section was generated by an AI
    // Bound work per loop even during a burst; leave remaining bytes in RX.
    if (++received > 1024 || uint32_t(micros() - receiveStartUs) >= 1500) return;
    if (serialJson.active || (state == AdaState::Header_A && Serial.peek() == '{')) {
      continuousSendLED = false;
      serialJson.push(char(Serial.read()), millis());
      if (serialJson.ready) { processSerialJson(); return; }
      continue;
    }
    // AI: end
    yield();
    byte next = Serial.peek();
    switch (state) {
      case AdaState::Header_A:
        if      (next == 'A')  { state = AdaState::Header_d; }
        else if (next == 0xC9) { state = AdaState::TPM2_Header_Type; } //TPM2 start byte
        else if (next == 'I')  { handleImprovPacket(); return; }
        else if (next == 'v')  { Serial.print("WLED"); Serial.write(' '); Serial.println(VERSION); }
        else if (next == 0xB0) { updateBaudRate( 115200); }
        else if (next == 0xB1) { updateBaudRate( 230400); }
        else if (next == 0xB2) { updateBaudRate( 460800); }
        else if (next == 0xB3) { updateBaudRate( 500000); }
        else if (next == 0xB4) { updateBaudRate( 576000); }
        else if (next == 0xB5) { updateBaudRate( 921600); }
        else if (next == 0xB6) { updateBaudRate(1000000); }
        else if (next == 0xB7) { updateBaudRate(1500000); }
        else if (next == 'l')  { sendJSON(); } // Send LED data as JSON Array
        else if (next == 'L')  { ++colorRequests; sendBytes(); } // Send LED data as TPM2 Data Packet
        else if (next == 'o')  { continuousSendLED = false; } // Disable Continuous Serial Streaming
        else if (next == 'O')  { continuousSendLED = true; } // Enable Continuous Serial Streaming
        break;
      case AdaState::Header_d:
        if (next == 'd') state = AdaState::Header_a;
        else             state = AdaState::Header_A;
        break;
      case AdaState::Header_a:
        if (next == 'a') state = AdaState::Header_CountHi;
        else             state = AdaState::Header_A;
        break;
      case AdaState::Header_CountHi:
        pixel = 0;
        count = next * 0x100;
        check = next;
        state = AdaState::Header_CountLo;
        break;
      case AdaState::Header_CountLo:
        count += next + 1;
        check = check ^ next ^ 0x55;
        state = AdaState::Header_CountCheck;
        break;
      case AdaState::Header_CountCheck:
        if (check == next) state = AdaState::Data_Red;
        else               state = AdaState::Header_A;
        break;
      case AdaState::TPM2_Header_Type:
        state = AdaState::Header_A; //(unsupported) TPM2 command or invalid type
        if (next == 0xDA) state = AdaState::TPM2_Header_CountHi; //TPM2 data
        else if (next == 0xAA) Serial.write(0xAC); //TPM2 ping
        break;
      case AdaState::TPM2_Header_CountHi:
        pixel = 0;
        count = (next * 0x100) /3;
        state = AdaState::TPM2_Header_CountLo;
        break;
      case AdaState::TPM2_Header_CountLo:
        count += next /3;
        state = AdaState::Data_Red;
        break;
      case AdaState::Data_Red:
        red   = next;
        state = AdaState::Data_Green;
        break;
      case AdaState::Data_Green:
        green = next;
        state = AdaState::Data_Blue;
        break;
      case AdaState::Data_Blue:
        byte blue  = next;
        if (!realtimeOverride) setRealtimePixel(pixel++, red, green, blue, 0);
        if (--count > 0) state = AdaState::Data_Red;
        else {
          realtimeLock(realtimeTimeoutMs, REALTIME_MODE_ADALIGHT);

          if (!realtimeOverride) strip.show();
          state = AdaState::Header_A;
        }
        break;
    }

    // All other received bytes will disable Continuous Serial Streaming
    if (continuousSendLED && next != 'O'){
      continuousSendLED = false;
    }

    Serial.read(); //discard the byte
  }

  // If Continuous Serial Streaming is enabled, send new LED data as bytes
  if (continuousSendLED && (lastUpdate != strip.getLastShow())){
    sendBytes();
    lastUpdate = strip.getLastShow();
  }
}
